#include "ezlocalai/ctts_cache.hpp"
#include "ezlocalai/llama_tts.hpp"
#include "whisper_transcription_test.hpp"
#include <zlib.h>
using namespace transcription_test;
using Ordered=nlohmann::ordered_json;
std::string hex_bytes(const std::string &input) { std::string out; const char *digits="0123456789abcdef"; for(unsigned char c:input) { out+=digits[c>>4]; out+=digits[c&15]; } return out; }
std::string substituted(std::string value,const std::string &from,const std::string &to) { size_t at=0; while((at=value.find(from,at))!=std::string::npos) { value.replace(at,from.size(),to); at+=to.size(); } return value; }
Json tree(const fs::path &root) { Json out=Json::object(); for(const auto &entry:fs::recursive_directory_iterator(root,fs::directory_options::skip_permission_denied)) { const auto path=entry.path(); const auto key=path.lexically_relative(root).string(); if(entry.is_symlink()) out[key]={{"kind","symlink"},{"target",fs::read_symlink(path).string()}}; else if(entry.is_directory()) out[key]={{"kind","dir"}}; else { Json bytes; try { bytes=hex_bytes(read(path)); } catch(const std::exception &) {} out[key]={{"kind","file"},{"data",bytes}}; } } return out; }
int main(int argc,char **argv) { try {
    expect(argc==3,"source and fixture"); gzFile file=gzopen(argv[2],"rb"); expect(file,"open gzip"); std::string content; char buffer[65536]; int size; while((size=gzread(file,buffer,sizeof(buffer)))>0) content.append(buffer,size); const auto end=gzclose(file); expect(size==0&&end==Z_OK,"complete gzip"); std::istringstream input(content); std::string line; std::getline(input,line); const auto header=Json::parse(line); expect(hash(read(fs::path(argv[1])/"ezlocalai/AudioCache.py"))==header.at("source_sha256"),"pinned cache source"); const auto original=fs::current_path(); size_t cases=0,operations=0;
    while(std::getline(input,line)) { if(line.empty()) continue; const auto row=Ordered::parse(line); ++cases; Temporary temporary; fs::current_path(temporary.path); struct Restore {fs::path path;~Restore(){fs::current_path(path);}} restore{original}; const auto root=temporary.path; struct Writable {fs::path root;~Writable(){ std::error_code error; fs::permissions(root/"outputs/cache",fs::perms::owner_all,fs::perm_options::add,error); }} writable{root}; const auto expand=[&](const Ordered &v){return Ordered::parse(substituted(v.dump(),"<ROOT>",root.string()));};
        for(const auto &e:row.at("setup")) { const auto path=root/e.at("path").get<std::string>(); fs::create_directories(path.parent_path()); if(e.at("kind")=="dir") fs::create_directories(path); else if(e.at("kind")=="symlink") fs::create_symlink(e.at("target").get<std::string>(),path); else { std::ofstream output(path,std::ios::binary); output<<unhex(e.at("data")); output.close(); if(e.contains("mode")) fs::permissions(path,fs::perms(e.at("mode").get<unsigned>())); } }
        size_t clock=0,generation=0; Json calls=Json::array(); std::unique_ptr<CttsAudioCache> cache; CttsCacheOperations ops; if(row.value("unlink_failure",false)) ops.duration_ms=[](const std::string &path) {const auto duration=ctts_cache_audio_duration(path);fs::permissions(fs::path(path).parent_path(),fs::perms::owner_read|fs::perms::owner_exec|fs::perms::group_read|fs::perms::group_exec|fs::perms::others_read|fs::perms::others_exec);return duration;}; ops.now=[&] { expect(clock<row.at("now_values").size(),"source clock count"); return row.at("now_values")[clock++].get<std::string>(); }; const auto snapshot=[&] {return Json{{"files",tree(root)},{"now_calls",clock},{"calls",calls},{"stats",cache?Json::parse(cache->raw_statistics()):Json()},{"config",cache?Json::parse(cache->configuration()):Json()}};};
        const CttsCacheGenerator generate=[&](const std::string &encoded) { calls.push_back(Json::parse(encoded)); const auto &actions=row.at("generations"); const auto &action=actions[(generation++)%actions.size()]; if(action.contains("error")) throw TtsError("RuntimeError","generation failed"); return unhex(action.at("data")); };
        const auto normalize=[&](const Json &v) {return Json::parse(substituted(v.dump(),root.string(),"<ROOT>"));}; Json startup;
        try { cache=std::make_unique<CttsAudioCache>(expand(row.at("config")).dump(),ops); startup["value"]=snapshot(); } catch(const TtsError &e) { startup={{"error",{e.category,e.what()}},{"state",snapshot()}}; }
        compare_json(normalize(startup),row.at("startup"),"cache startup "+std::to_string(cases)+" "+row.at("name").get<std::string>());
        if(cache) { size_t index=0; for(const auto &raw:row.at("operations")) { const auto action=expand(raw); const auto name=action.at("op").get<std::string>(); Json result; ++operations;
            try {
                if(name=="get") { const auto value=cache->get(action.at("key")); result["value"]=value?Json(hex_bytes(*value)):Json(); }
                else if(name=="store") { auto metadata=action.at("metadata").dump(); result["value"]=cache->store(action.at("key"),unhex(action.at("data")),metadata); result["metadata"]=Json::parse(metadata); }
                else if(name=="stats") result["value"]=Json::parse(cache->statistics());
                else if(name=="key") result["value"]=ctts_cache_key(action.at("text"),action.at("voice"),action.at("language"),action.at("extra").dump());
                else if(name=="select") { const auto value=cache->select_best_audio(generate,action.at("parameters").dump()); result["value"]={{"audio",hex_bytes(value.audio)},{"metadata",Json::parse(value.metadata)}}; }
                else { result["value"]=nullptr; if(name=="clear") cache->clear(action.contains("voice")?std::optional<std::string>(action.at("voice").get<std::string>()):std::nullopt); else if(name=="remove") cache->remove(action.at("key")); else if(name=="cleanup") cache->cleanup_expired(); else if(name=="size") cache->check_size(); else if(name=="warm") cache->warm(action.at("phrases").get<std::vector<std::string>>(),action.at("voice"),action.at("language"),generate,action.at("parameters").dump()); else if(name=="key_store_orphan") { const auto key=ctts_cache_key(action.at("text"),action.at("voice"),action.at("language")); const auto config=Json::parse(cache->configuration()); std::ofstream out(fs::path(config.at("cache_dir").get<std::string>())/"audio"/(key+".wav")); out<<"orphan"; } }
            } catch(const TtsError &e) { result=Json{{"error",{e.category,e.what()}}}; }
            result["state"]=snapshot(); const auto expected=row.at("results")[index++]; compare_json(normalize(result),expected,"cache "+std::to_string(cases)+" operation "+std::to_string(index)+" "+name);
        } }
    }
    expect(cases==header.at("cases")&&operations==header.at("operations"),"complete cache comparisons"); std::cout<<cases<<" source AudioCache scenarios and "<<operations<<" operations match, including complete filesystem/metadata state\n"; return 0;
} catch(const std::exception &e) { std::cerr<<e.what()<<'\n'; return 1; } }
